# Check listing hex against the stock image. Read-only.
# File offset = address - 0x60021020.
# Do not edit this file after it has run.
import re
from pathlib import Path

BASE = 0x60021020
img = Path('inputs/00_0100_50000020.decoded.bin').read_bytes()
out = []
pat = re.compile(r'^([0-9a-fA-F]{8})\t([0-9a-fA-F]+)\t')
root = Path('work/out/listings')
for path in sorted(root.glob('*.txt')):
    checked = 0
    bad = 0
    samples = []
    for line in path.read_text(encoding='utf-8', errors='replace').splitlines():
        m = pat.match(line)
        if not m:
            continue
        addr = int(m.group(1), 16)
        hx = m.group(2).lower()
        off = addr - BASE
        nbytes = len(hx) // 2
        if off < 0 or off + nbytes > len(img) or len(hx) % 2:
            bad += 1
            checked += 1
            if len(samples) < 3:
                samples.append(f'{addr:08x} out of image {hx}')
            continue
        got = img[off:off + nbytes].hex()
        checked += 1
        if got != hx:
            bad += 1
            if len(samples) < 3:
                samples.append(f'{addr:08x} listing {hx} image {got}')
    out.append(f'{path.name} checked {checked} mismatches {bad}')
    out.extend('  ' + s for s in samples)
text = '\n'.join(out) + '\n'
Path('work/out/listing-bytes-s4.txt').write_text(text, encoding='utf-8')
print(text)
